# order_processing.py

def validate_items(items):
    if not items:
        raise ValueError("The list of items cannot be empty.")
    for item in items:
        if item['price'] < 0 or item['quantity'] < 0:
            raise ValueError("Item price and quantity must be non-negative.")

def calculate_pricing(items, is_vip=False):
    subtotal = sum(item['price'] * item['quantity'] for item in items)
    discount = 0.1 if is_vip else 0
    total = subtotal - (subtotal * discount) + (subtotal * 0.08)  # Adding 8% tax
    return total

def format_receipt(items, total):
    receipt = "\n".join(f"{item['quantity']} x {item['name']}: ${item['price']:.2f}" for item in items)
    receipt += f"\nTotal: ${total:.2f}"
    return receipt

def process_order(items, is_vip=False):
    validate_items(items)
    total = calculate_pricing(items, is_vip)
    receipt = format_receipt(items, total)
    return {'total': total, 'receipt': receipt}
